/* Types */
/**
 *  `ui.about`: the resource kind (the short form, a string) or the object
 *  form `{ resource, accepts? }` that also filters the items.
 */
export type About = string | AboutItem;

export type AboutItem = {
	resource: string,
	accepts?: ItemAccepts | null,
};

export type AcceptedValues = {
	column: string,
	values: string[],
};

/**
 *  What a run changes, and so whether it is recorded and who may make it —
 *  a scope's (`Scope::access`) and a command's (`CommandSpec::access`, the
 *  strongest among the scopes it needs). Ordered weakest first. Not where
 *  its handler runs: that is the operation's handler, in the bus's
 *  transaction or outside it (`config.write`'s `set` is one transaction,
 *  the file written after it commits; `providers.sync` commits each batch
 *  in its own).
 */
export type Access =
/**  Changes only what the person sees (open a page, find in a file). */
"view" |
/**  Reads, changes nothing (`sql.read`). */
"read" |
/**
 *  Changes oxplow's own records (filing and editing tasks): recorded,
 *  open to any thread.
 */
"record" |
/**
 *  Changes something outside oxplow's records — files, git, processes,
 *  the configuration: recorded, and an agent's or job's run must be
 *  bound to an open thread (the worktree it changes).
 */
"write";

/**  An action point an extension declares. */
export type ActionPointDecl = {
	/**  `<namespace>/<name>`. */
	id: string,
	label: string,
	doc: string | null,
	context: ContextKey[],
	/**
	 *  The context key (a `uri`) naming the item it acts on: a joined
	 *  command's `ui.accepts` is checked against that item's store.
	 */
	item: string | null,
};

/**
 *  An action point a run placed: the point and the context the page gave
 *  it (`context:` bound from the page's params and loaders).
 */
export type ActionPointRun = {
	point: string,
	context: { [key in string]: unknown },
};

/**
 *  What becomes of the page a viz is on after one of its actions (or its
 *  form) ran a command whose `ui.open_after` names a page.
 */
export type ActionThen =
/**  The page opens in this tab; Back returns to the viz's page. */
"open" |
/**
 *  The page takes this tab and the viz's page leaves its history: Back
 *  never returns to a submitted form. A page that can't live in a tab
 *  (an agent session) closes this one and is focused.
 */
"replace" |
/**  Nothing opens; the viz's page stays (a form for the next entry). */
"stay" |
/**  The viz's page closes (it showed what the command removed). */
"close";

/**
 *  Guidance an extension gives the coding agent: a query over the semantic
 *  layer, run by core at `on`, with `:thread_id`, `:stream_id`, `:turn_id`,
 *  and `:request_id` (the request of the turn the trigger belongs to)
 *  bound. Each result row's `message` column is a line of guidance.
 */
export type Advisory = {
	id: string,
	on: AdvisoryOn,
	query: string,
	oncePer: AdvisoryOncePer,
	/**  Line put above the messages (e.g. `# Metric deltas (this request)`). */
	heading: string | null,
	audience: AdvisoryAudience,
	/**
	 *  The capabilities (or features) it needs; without them it doesn't
	 *  run.
	 */
	needs: string[],
	when?: ConfigCondition | null,
	/**
	 *  What a post-tool advisory runs after on the tool call's event, as
	 *  resolved refs (`.context/extensions-events.md` "Ordering"): a core
	 *  consumer such as `collection`, or an effect or a collector. None runs
	 *  it as soon as the call is projected.
	 */
	after?: string[],
};

/**  Who a hint is for. */
export type AdvisoryAudience =
/**  The coding agent: delivered on its next prompt or tool call. */
"agent" |
/**  A person: raised in Alerts until they dismiss it. */
"person";

/**  When core runs an advisory. */
export type AdvisoryOn =
/**
 *  After each agent tool call; results go to the agent as that call's
 *  context and are recorded as nudges.
 */
"post-tool-use" |
/**  On each prompt the human sends; results join the prompt's context. */
"prompt" |
/**
 *  When a turn ends (its `thread.checkpoint`): what the turn left
 *  behind, delivered when the agent next hears from oxplow (the next
 *  prompt, else the next tool call).
 */
"turn-end";

/**  How often the same advisory may reach the agent. */
export type AdvisoryOncePer =
/**
 *  Once per request on the thread, the first time the query returns
 *  rows (the request of the turn the trigger belongs to): the next
 *  request is fresh. The default.
 */
"request" |
/**
 *  Once per thread per `key` value: each row's `key` column fires
 *  once (put `:request_id` in the key for once per request per row).
 */
"row" |
/**  Every time, whenever the query returns rows. */
"turn" |
/**  Once per thread, the first time the query returns rows. */
"thread" |
/**  Once per agent session on the thread (the harness's session id). */
"session" |
/**  Once per thread per day (UTC). */
"day";

/**
 *  One agent context as the extension declares it. A new condition on
 *  when it runs is a field here beside `needs`.
 */
export type AgentContextDecl = {
	id: string,
	/**
	 *  What it tells the agent, for a person reading the manifest or the
	 *  catalog.
	 */
	doc: string,
	/**  What it needs active (`snapshots`); without it, it doesn't run. */
	needs: string[],
	/**
	 *  The extension's own setting that offers it (as a skill's `when:`);
	 *  `None`: always.
	 */
	when: ConfigCondition | null,
	query: string,
};

export type AgentSessionId = string;

export type AgentStatus = {
	thread_id: ThreadId,
	/**  The thread's stream. */
	stream_id: StreamId,
	/**
	 *  The agent session it is the status of; `None` for activity no
	 *  session claims (an agent oxplow didn't start).
	 */
	agent_session_id: AgentSessionId | null,
	state: AgentStatusState,
	detail: string | null,
	updated_at: Timestamp,
};

export type AgentStatusState = "idle" | "running" | "awaiting_user" | "stopped" | "error" |
/**
 *  Derived-only: the hook log says Running but no event has
 *  arrived for longer than the stall threshold. Claude Code emits
 *  no hook when a turn dies on an API error and the process drops
 *  back to its prompt, so a wall-clock check is the only way to
 *  notice. Never logged: `agent.status.changed` has no such state.
 */
"stalled";

/**  Which body of the call. */
export type AiCallBody =
/**
 *  What the model was asked: `{ system, prompt, json }` or `{ state,
 *  questions }`.
 */
"request" |
/**  What it answered: `{ text }` or `{ answers }`. */
"response";

/**  An `ai_call` row. */
export type AiCallId = number;

/**  The `ai_context:` block. All keys are optional. */
export type AiContext = {
	/**  When to use this and how to read it. */
	instructions?: string | null,
	/**  Other names a person or agent may call it. */
	synonyms?: string[],
	/**  Example questions it answers. */
	examples?: string[],
};

/**  A named model need of one extension. */
export type AiProfileDecl = {
	id: string,
	description: string,
	/**  The built-in role whose model serves it until the person binds one. */
	fallback: BuiltinRole,
	/**  What the bound model must support. */
	features: ModelFeature[],
};

/**  One thing a binding may be restricted from. */
export type AiRestriction =
/**  Any tool: a request offering the model tools to call. */
"tools" |
/**  The `query_sql` tool: reading oxplow's models through SQL. */
"sql" |
/**  A streamed reply. */
"streaming" |
/**  Image input. */
"images";

export type AiSettings = {
	providers: ProviderStatus[],
	/**
	 *  The built-in roles in `BuiltinRole::ALL` order, then the active
	 *  extensions' AI profiles, then bindings for profiles nothing declares.
	 */
	roles: RoleStatus[],
	/**  The kinds a provider can be: the registered model providers. */
	kinds: ProviderKindInfo[],
};

/**  A viz's alert, evaluated on one run. */
export type AlertState = {
	firing: boolean,
	/**  Rows the run returned. */
	count: number,
	/**  The watched column's value, for a threshold alert. */
	value: number | null,
	/**  What the badge says, e.g. `3 rows` or `Coverage low: 72`. */
	message: string,
};

export type AppVersion = {
	version: string,
};

/**
 *  A value flowing into a command's arg or another page's param:
 *  declarative, never an expression.
 */
export type ArgSource =
/**  One of the page's params. */
({ param: string }) & { from?: never } |
/**  An earlier loader's column, from its first row (`<loader>.<col>`). */
({ from: string }) & { param?: never } |
/**  A literal value. */
unknown;

/**
 *  Whether the handler runs inside the bus's transaction (with the command run
 *  row and `command.executed`), or outside it, against a system the bus
 *  doesn't own — a VCS, a provider process, a collector's script — and is
 *  recorded after it returns (`External`). A `Dispatch` command decides
 *  per input (the `task.*` verbs: oxplow's own items in the
 *  transaction, another provider's through its process) and then runs
 *  exactly as one or the other. A test lists the `External` and the
 *  `Dispatch` commands, so each one is a reviewed choice.
 */
export type Atomicity = "tx" | "external" | "dispatch";

/**
 *  Result of `attach_or_create` — the session id plus a base64
 *  snapshot of the replay buffer that the renderer should write into
 *  a fresh xterm before starting to consume live events.
 */
export type AttachResult = {
	sessionId: string,
	replayB64: string,
	/**
	 *  The PTY's size now: the owner's, which a pane that is not the
	 *  owner can draw.
	 */
	cols: number,
	rows: number,
	/**
	 *  The page load that owns the size (`oxplow-app::terminal_sessions`:
	 *  the one that last typed), and the caller's own: a pane is the owner
	 *  when they are equal. Null for a caller with no page load.
	 */
	owner: string | null,
	you: string | null,
};

export type BackgroundTask = {
	id: string,
	kind: BackgroundTaskKind,
	label: string,
	detail: string | null,
	/**  0..=1 for determinate, `None` for indeterminate. */
	progress: number | null,
	status: BackgroundTaskStatus,
	started_at: number,
	ended_at: number | null,
	error: string | null,
	/**
	 *  Producer-supplied opaque JSON attached at complete/fail.
	 *  Stored as a string so the bindings stay simple — the producer
	 *  is expected to JSON-stringify before passing.
	 */
	result_json: string | null,
};

export type BackgroundTaskKind = "vcs" | "code-quality" | "lsp" | "snapshot" |
/**
 *  Recomputing code metrics over the whole tree (the metric baseline).
 *  Slow and CPU-hungry — it must be visible, or "why is oxplow pegging a core?"
 *  has no answer.
 */
"metrics" |
/**  A command a person ran in the background (its `CommandUi.background`). */
"command";

export type BackgroundTaskStatus = "running" | "done" | "failed";

/**  Edge plus a best-effort renderer label for its other end. */
export type BacklinkEdge = {
	/**  The URI that refers. */
	source: string,
	/**  The URI it refers to. */
	target: string,
	ref_type: string,
	source_extra: string | null,
	/**
	 *  Human label for the other end (the source of a backlink, the
	 *  target of an outbound edge): knowledge page title, task title, commit
	 *  subject, …. The renderer falls back to the URI when None.
	 */
	source_label: string | null,
	/**
	 *  Whether anything resolves the row the label belongs to. A link to
	 *  a URI nothing resolves — an extension gone, a record deleted — is
	 *  a dead link the renderer shows as its raw text.
	 */
	resolved: boolean,
};

/**
 *  What a page's badge counts: a loader's first row's `column` (else
 *  its first), or its row count when the column isn't a number.
 */
export type Badge = {
	loader: string,
	column?: string | null,
};

/**  Who last changed one line. */
export type BlameLine = {
	/**  1-based. */
	line: number,
	/**
	 *  The revision that last changed the line; `None` for a line not
	 *  committed yet (blaming the working tree).
	 */
	revision: string | null,
	author: string,
	email: string,
	time: number,
	summary: string,
};

/**
 *  What a task tracker's stage means to core: the bucket each of its declared
 *  stages ([`StageDecl`]) is in. Core acts on buckets only — `backlog` is
 *  filed but not ready, `todo` is ready (what an idle thread may pull),
 *  `in_progress` is started, `blocked` waits on an answer, `done` and
 *  `canceled` are closed — and the screens draw the list's own stages.
 */
export type Bucket = "backlog" | "todo" | "in_progress" | "blocked" | "done" | "canceled";

/**
 *  What a deploy builds before it copies: `run` in the source folder, as
 *  the person, then `output` is copied into the deployment. The hash is of
 *  the inputs — every file but `output` and the `exclude` folders — and
 *  `run` itself, so a build's output never changes what is deployed.
 */
export type Build = Build_Serialize | Build_Deserialize;

/**
 *  What a deploy builds before it copies: `run` in the source folder, as
 *  the person, then `output` is copied into the deployment. The hash is of
 *  the inputs — every file but `output` and the `exclude` folders — and
 *  `run` itself, so a build's output never changes what is deployed.
 */
export type Build_Deserialize = {
	/**
	 *  The command, run with `/bin/sh -c` in the source folder with the
	 *  person's environment. A new or changed one is approved at deploy.
	 */
	run: string,
	/**
	 *  The folder it writes (`dist`), relative to the extension: copied
	 *  into the deployment, never hashed.
	 */
	output: string,
	/**  Folders neither hashed nor deployed (`node_modules`). */
	exclude?: string[],
};

/**
 *  What a deploy builds before it copies: `run` in the source folder, as
 *  the person, then `output` is copied into the deployment. The hash is of
 *  the inputs — every file but `output` and the `exclude` folders — and
 *  `run` itself, so a build's output never changes what is deployed.
 */
export type Build_Serialize = {
	/**
	 *  The command, run with `/bin/sh -c` in the source folder with the
	 *  person's environment. A new or changed one is approved at deploy.
	 */
	run: string,
	/**
	 *  The folder it writes (`dist`), relative to the extension: copied
	 *  into the deployment, never hashed.
	 */
	output: string,
	/**  Folders neither hashed nor deployed (`node_modules`). */
	exclude?: string[],
};

/**
 *  The jobs oxplow itself gives models. Every extension can name them.
 *  Default is the model every other role uses while it has none of its
 *  own; an extension's AI profile falls back to Default unless it names
 *  another built-in, whose own chain ends at Default.
 */
export type BuiltinRole = "default" | "summarize" | "decide";

/**  A size in bytes (the blob store's total, say). */
export type ByteSize = number;

/**  One Settings category an extension declares. */
export type CategoryDeclaration = {
	title: string,
	description?: string,
	/**  Lower first among all categories (core's run 0 to 110). */
	order?: number,
};

/**
 *  One choice for a form field: the value it submits, what the person
 *  reads, and the heading it sits under.
 */
export type Choice = {
	value: string,
	label: string,
	group: string | null,
};

/**  One value a choice param takes, and what the viewer sees for it. */
export type ChoiceOption = ChoiceOption_Serialize | ChoiceOption_Deserialize;

/**  One value a choice param takes, and what the viewer sees for it. */
export type ChoiceOption_Deserialize = {
	value: string,
	label: string,
	/**
	 *  An icon oxplow draws (`ICONS`): where the choice is a panel header's
	 *  toggle, the option is that icon alone, its label the hover.
	 */
	icon?: string | null,
};

/**  One value a choice param takes, and what the viewer sees for it. */
export type ChoiceOption_Serialize = {
	value: string,
	label: string,
	/**
	 *  An icon oxplow draws (`ICONS`): where the choice is a panel header's
	 *  toggle, the option is that icon alone, its label the hover.
	 */
	icon?: string | null,
};

/**
 *  Where a choice field's choices come from: a page's loader or a viz
 *  (`<extension>/<page>#<loader>`, `<extension>/<slug>`), its rows `value`,
 *  `label` and an optional `group`. As a name, run with the form's params;
 *  as `{ from, params, open }`, also with `params`, each bound like the
 *  form's input (`{{param.x}}`, a row form's `{{row.x}}`: one provider's
 *  models), and with `open: true` the choices are suggestions the person
 *  may type past (a model id no list knows).
 */
export type ChoiceSource = ChoiceSource_Serialize | ChoiceSource_Deserialize;

/**
 *  Where a choice field's choices come from: a page's loader or a viz
 *  (`<extension>/<page>#<loader>`, `<extension>/<slug>`), its rows `value`,
 *  `label` and an optional `group`. As a name, run with the form's params;
 *  as `{ from, params, open }`, also with `params`, each bound like the
 *  form's input (`{{param.x}}`, a row form's `{{row.x}}`: one provider's
 *  models), and with `open: true` the choices are suggestions the person
 *  may type past (a model id no list knows).
 */
export type ChoiceSource_Deserialize = string | ChoiceSpec_Deserialize;

/**
 *  Where a choice field's choices come from: a page's loader or a viz
 *  (`<extension>/<page>#<loader>`, `<extension>/<slug>`), its rows `value`,
 *  `label` and an optional `group`. As a name, run with the form's params;
 *  as `{ from, params, open }`, also with `params`, each bound like the
 *  form's input (`{{param.x}}`, a row form's `{{row.x}}`: one provider's
 *  models), and with `open: true` the choices are suggestions the person
 *  may type past (a model id no list knows).
 */
export type ChoiceSource_Serialize = string | ChoiceSpec_Serialize;

export type ChoiceSpec = ChoiceSpec_Serialize | ChoiceSpec_Deserialize;

export type ChoiceSpec_Deserialize = {
	from: string,
	params?: { [key in string]: unknown },
	open?: boolean,
};

export type ChoiceSpec_Serialize = {
	from: string,
	params?: { [key in string]: unknown },
	open?: boolean,
};

/**  How a client authenticates to a token endpoint. */
export type ClientAuth = "basic" | "post";

/**
 *  A derived collector's input query (`input`): read-only SQL over the
 *  semantic layer, handed over as `input.rows`.
 */
export type CollectorInput = {
	sql: string,
	/**
	 *  A bound taken on purpose: at most this many rows, with
	 *  `input.complete` saying whether they were all of them. Absent, the
	 *  input is every row or the run fails.
	 */
	limit: number | null,
};

/**  Outcome of one run, as reported to the UI / agent. */
export type CollectorRunReport = {
	owner: string,
	id: string,
	/**  An entity collector's rows per entity after the run. */
	rowCounts: { [key in string]: number },
	/**  A fact collector's facts recorded. */
	facts: number,
	/**
	 *  What a run skipped and why: shared-model rows it quarantined, each
	 *  naming the row and column.
	 */
	problems?: string[],
};

/**  What runs a collector. */
export type CollectorRuntime =
/**
 *  A program: can reach the network and credentials, so it needs a
 *  person's approval to run.
 */
"exec" |
/**
 *  A sandboxed Starlark script: no I/O, so no approval — unless it
 *  calls a model (`ai_*`), which spends the person's key.
 */
"starlark" |
/**  A sandboxed jq program: no I/O, so no approval. */
"jaq" |
/**
 *  A provider instance's collector (`oxplow.provider.sync`): its records
 *  land in the capability's dataset (`v_oxplow_task`).
 */
"read";

/**  One declared collector. */
export type CollectorSpec = CollectorSpec_Serialize | CollectorSpec_Deserialize;

/**  One declared collector. */
export type CollectorSpec_Deserialize = {
	/**  Unique in its owner; a dotted id (`repo.scan_clone`) is fine. */
	id: string,
	doc: string,
	runtime: CollectorRuntime,
	/**
	 *  The program or script, relative to its owner's folder (the
	 *  extension's, or the project's); absent for `read`.
	 */
	entry: string | null,
	/**  For `read`: the provider collector it runs. */
	provider: ProviderRead | null,
	trigger: Trigger_Deserialize,
	/**
	 *  With an `on:` trigger: what it runs after on one event — an effect,
	 *  a collector or a core consumer (`change.analyze`), as written; the
	 *  catalog resolves it to refs.
	 */
	after: string[],
	/**
	 *  A script's input query: read-only SQL over the semantic layer,
	 *  handed over as `input.rows`. `:stream_id`, `:snapshot_id`,
	 *  `:thread_id` and `:turn_id` bind the triggering
	 *  event's anchors, `:event_id` its id and `:event_seq` its seq (NULL
	 *  otherwise).
	 */
	input: CollectorInput | null,
	/**  A report file handed over as `input.report`. */
	report: ReportInput | null,
	sync: CollectorSync,
	/**  Host environment variables an exec collector gets. */
	env: string[],
	/**  Hosts an exec collector may reach; part of what a person approves. */
	network: string[],
	/**  Keychain secrets an exec collector gets as environment variables. */
	credentials: string[],
	/**
	 *  The services a Starlark collector's script uses beyond what its kind
	 *  implies (`tree.read`, `sql.read`, `ai.compute`; `oxplow_domain::service`).
	 */
	needs?: string[],
	entities: EntityDecl[],
	/**
	 *  The measures its facts land on (`repo.rust_clone`); a fact on any
	 *  other is dropped.
	 */
	facts: string[],
	/**
	 *  A fact collector that reads the whole tree as of the snapshot on
	 *  every run, so its capture restates every file (a duplication scan),
	 *  rather than only the files the snapshot changed.
	 */
	wholeTree?: boolean,
	/**
	 *  A report collector's kind: it parses `report` with `entry` and its
	 *  output joins the run (`on: { run: … }`).
	 */
	records: Records | null,
};

/**  One declared collector. */
export type CollectorSpec_Serialize = {
	/**  Unique in its owner; a dotted id (`repo.scan_clone`) is fine. */
	id: string,
	doc: string,
	runtime: CollectorRuntime,
	/**
	 *  The program or script, relative to its owner's folder (the
	 *  extension's, or the project's); absent for `read`.
	 */
	entry: string | null,
	/**  For `read`: the provider collector it runs. */
	provider: ProviderRead | null,
	trigger: Trigger_Serialize,
	/**
	 *  With an `on:` trigger: what it runs after on one event — an effect,
	 *  a collector or a core consumer (`change.analyze`), as written; the
	 *  catalog resolves it to refs.
	 */
	after: string[],
	/**
	 *  A script's input query: read-only SQL over the semantic layer,
	 *  handed over as `input.rows`. `:stream_id`, `:snapshot_id`,
	 *  `:thread_id` and `:turn_id` bind the triggering
	 *  event's anchors, `:event_id` its id and `:event_seq` its seq (NULL
	 *  otherwise).
	 */
	input: CollectorInput | null,
	/**  A report file handed over as `input.report`. */
	report: ReportInput | null,
	sync: CollectorSync,
	/**  Host environment variables an exec collector gets. */
	env: string[],
	/**  Hosts an exec collector may reach; part of what a person approves. */
	network: string[],
	/**  Keychain secrets an exec collector gets as environment variables. */
	credentials: string[],
	/**
	 *  The services a Starlark collector's script uses beyond what its kind
	 *  implies (`tree.read`, `sql.read`, `ai.compute`; `oxplow_domain::service`).
	 */
	needs: string[],
	entities: EntityDecl[],
	/**
	 *  The measures its facts land on (`repo.rust_clone`); a fact on any
	 *  other is dropped.
	 */
	facts: string[],
	/**
	 *  A fact collector that reads the whole tree as of the snapshot on
	 *  every run, so its capture restates every file (a duplication scan),
	 *  rather than only the files the snapshot changed.
	 */
	wholeTree: boolean,
	/**
	 *  A report collector's kind: it parses `report` with `entry` and its
	 *  output joins the run (`on: { run: … }`).
	 */
	records: Records | null,
};

/**  How a run's entities land. */
export type CollectorSync =
/**  Each run restates every entity (one it doesn't mention is emptied). */
"replace" |
/**
 *  Each run adds or updates rows by key, and removes the keys it lists
 *  under `deleted`; an entity it doesn't mention is left alone.
 */
"upsert";

/**  How a column's value reads in the UI. An agent reads the raw value. */
export type ColumnFormat =
/**  A timestamp's date. */
"date" |
/**  A timestamp's date and time. */
"datetime" |
/**  A timestamp as how long ago (`3 h ago`). */
"relative" |
/**  A byte count (`1.2 MB`). */
"bytes" |
/**  Milliseconds as a duration (`1.4 s`, `3 m`). */
"duration" |
/**  A whole number with separators (`12,345`). */
"integer" |
/**  A fraction 0–1 as a percentage (`42%`). */
"percent" |
/**
 *  A series (a JSON array of numbers) as a small line, with its
 *  latest value.
 */
"sparkline" |
/**  A short value as a pill, in the column's `tone`. */
"badge" |
/**
 *  Inline markdown (a description's `first_sentence`), drawn on its
 *  line: emphasis, code and links (a wikilink opens its page, by its
 *  title); a block's marks unwrap. An agent reads it as written.
 */
"markdown" |
/**
 *  A list of items (a JSON array): each element is a string or
 *  `{ "text": …, "hint"?: …, "uri"?: … }`, drawn inline separated by
 *  ` · `; `hint` is the item's hover text, `uri` makes it a link. An
 *  agent reads them joined by ` · `, a hint in parentheses.
 */
"items" |
/**
 *  Short marks (a JSON array): each element is a string or `{ "text":
 *  …, "tone"?: …, "hint"?: … }`, drawn as small tight letters, each in
 *  its own `tone` (`accent`, `success`, `warning`, `danger`, `muted`) —
 *  a file's A/M/D, a change's `+3 −1`. `hint` is the mark's hover. An
 *  agent reads them joined by spaces, a hint in parentheses.
 */
"marks" |
/**
 *  The lanes of the graph the rows form, as `git log --graph` draws
 *  them: the column's value is the row's id and `parents` names the
 *  column of its parents' ids. For a `table`, whose rows are drawn in the
 *  order given, each child before its parents. An agent reads no lanes.
 */
"lanes" |
/**
 *  Who caused it (a JSON object `{ "kind": "agent" | "you" |
 *  "extension" | "page", "label": …, "uri"?: … }`): a small chip with
 *  the kind's icon, a link when it has a `uri` (an agent's thread, an
 *  extension's page). An agent reads `<kind> <label>` (`agent in
 *  <label>`; "You" alone).
 */
"source";

/**  Makes a column's cells link to a page. */
export type ColumnLink = {
	kind: LinkKind,
	/**  Result column holding the target id. Defaults to the column itself. */
	from?: string | null,
	/**  For `file` / `diff-at`: result column holding a line number to open at. */
	line?: string | null,
	/**  For `diff-at`: column holding the older side's label. */
	base?: string | null,
	/**  For `diff-at` / `compare`: column holding the newer side's label. */
	head?: string | null,
};

/**  Declared type of an entity column. */
export type ColumnType = "text" | "int" | "real" | "bool" |
/**  An RFC 3339 timestamp, stored as text. */
"time";

/**
 *  A command by name with its input — what an inverse is, and what
 *  `run_command` receives.
 */
export type CommandCall = {
	name: string,
	input: unknown,
};

/**
 *  An example run of a command: its input, and the commands its script
 *  should compose, in order — or the refusal it should make (checked by
 *  `oxplow extension check` / Settings).
 */
export type CommandExample = {
	name: string,
	input: unknown,
	/**
	 *  Answers standing in for the scopes' own, per scope in call order
	 *  (so the example doesn't depend on the project's data); a scope
	 *  without any is served for real.
	 */
	answers: { [key in string]: unknown[] },
	expectCommands: string[],
	/**  A part of the reason the script should refuse with. */
	refused: string | null,
};

/**  What runs an extension's command. */
export type CommandHandler =
/**  A Starlark script composing commands (`entry:`). */
{ kind: "script";
/**  The script, relative to the extension folder. */
entry: string } |
/**
 *  One operation of a scope (`scope:` + `op:`,
 *  `commands::ops`).
 */
{ kind: "scope"; scope: string; op: string } |
/**
 *  One operation of one of the extension's providers (`provider:` +
 *  `op:`): run on the instance its input names
 *  (`commands::ProviderRouter`).
 */
{ kind: "provider"; provider: string; op: string;
/**  It returns an inverse (its declarations say). */
undoable: boolean };

/**  A completed run. */
export type CommandOutcome = {
	result: unknown,
	/**  The `command_run` row; `None` for a `Read` command. */
	command_run_id: number | null,
	/**  The `command.executed` event; `None` for a `Read` command. */
	event_id: EventId | null,
	/**
	 *  Present when the command is undoable: `commands.undo(command_run_id)`
	 *  runs it.
	 */
	inverse: CommandCall | null,
};

/**  A `command_run` row. */
export type CommandRunId = number;

/**  What a command declares about itself. */
export type CommandSpec = {
	/**
	 *  The command id: `<namespace>.<area>.<verb>`, snake_case —
	 *  `oxplow.thread.mark`, `acme_pr.issue.close`. The namespace
	 *  is its owner's (`oxplow` for core and oxplow's own extensions, an
	 *  extension's declared `namespace:` otherwise), so two extensions'
	 *  areas never collide. (A person reads the command's label, not its
	 *  id.)
	 */
	id: string,
	/**  One sentence for `list_commands` and the launcher. */
	summary: string,
	/**  JSON Schema for the input. */
	input_schema: unknown,
	/**
	 *  JSON Schema of its result, when its operation declares one: what an
	 *  MCP client gets as structured content beside the text.
	 */
	output_schema?: unknown | null,
	/**
	 *  A model's tool call inside a durable job may run it: only a
	 *  command its extension declared for that, and a job of the same
	 *  extension names in its `tools`. Anyone else — a person, an agent, a
	 *  page acting for either — may run every command: oxplow puts no wall
	 *  between a person and their agent (the agent's harness says what it
	 *  may call).
	 */
	job?: boolean,
	confirm: Confirm,
	/**
	 *  What a person is told when it asks, in place of its input and, for a
	 *  destructive one, the generic warning: `{{field}}` is that input.
	 */
	confirm_says?: string | null,
	/**  The handler returns an inverse, so `commands.undo` can apply it. */
	undoable: boolean,
	lifecycle: Lifecycle,
	atomicity: Atomicity,
	access: Access,
	/**
	 *  The scopes its handler calls (`sql.read`) and the capabilities, or
	 *  their features (`snapshots.contents`), it needs active; unmet, it
	 *  isn't offered and doesn't run (`.context/commands.md`).
	 */
	needs: string[],
	/**
	 *  How a person meets it — label, group, where it's offered and how
	 *  it runs from there. `None`: it isn't offered to a person by itself
	 *  (a step other commands compose, an agent's tool). Boxed: it is
	 *  large and most commands have none, and specs are moved and listed
	 *  by the hundred.
	 */
	ui?: CommandUi | null,
	/**
	 *  The scope operation behind it, when it is one: where it runs (a
	 *  window scope's runs in the window) and what it does.
	 */
	op?: OpRef | null,
	/**
	 *  Top-level input fields its record leaves out — a file's content —
	 *  kept as their size (`{ "omitted_bytes": n }`). The reserved `*`
	 *  marker omits the entire input, including non-object inputs: the run is still
	 *  recorded, the command run log doesn't grow by every file saved.
	 */
	unrecorded?: string[],
};

/**  A command as a person meets it. Agents ignore it. */
export type CommandUi = {
	/**  What a person reads: `Pull Changes`, `New Task…`. */
	label: string,
	/**  What search lists it under: `Git`, `Tasks`. */
	group?: string | null,
	/**  More words search matches it by. */
	keywords?: string[],
	/**
	 *  The ref kind it acts on (`task`, `request`): offered on that
	 *  ref's page and rows. `None`: it needs no ref, and search offers it.
	 */
	about?: About | null,
	/**
	 *  A column of `about`'s dataset row (the dataset its resource
	 *  resolves through) that must be truthy — not null, 0, `""` or false —
	 *  for the command to be offered on a ref of that kind: the same rule
	 *  as a page action's `when`. A ref whose state fails it isn't offered
	 *  the command at all (the daemon answers, `ref_commands`). Needs
	 *  `about`; the column is checked against the dataset when the
	 *  extensions load. Absent, every ref of the kind is offered it.
	 */
	about_when?: string | null,
	/**
	 *  A function of the command's `entry:` script that decides, for each
	 *  link of `about`'s kind that passes `about.accepts`, whether the
	 *  command is offered on it: called with `{ uri, kind, url?, path? }`,
	 *  offered when it returns `True`. The logic a pattern can't say (a
	 *  URL of a host the extension's settings name). Needs `about`; the
	 *  function is checked against the script when the extension loads.
	 */
	about_if?: string | null,
	/**
	 *  The named action point it joins (`<namespace>/<name>`, declared
	 *  by an extension's `action_points:`): the point's page places it,
	 *  and it runs with the point's context as its input. Excludes
	 *  `about` (an item command). Its `input` binds the context's keys
	 *  (`{ parent: "{{context.parent}}" }`, a key the page left out stays
	 *  unset); without one the input is the whole context.
	 */
	at?: string | null,
	/**
	 *  With `at`, at a point that names its item (`item:`): the stores
	 *  whose items it acts on (`{ store: <id> | [ids] }`, as `about`'s
	 *  `accepts`); the point offers it only for an item of one of them.
	 */
	accepts?: ItemAccepts | null,
	/**
	 *  The input it runs with. A string that is exactly `{{stream}}`,
	 *  `{{thread}}`, `{{uri}}` or `{{uri.id}}` is bound from where it runs;
	 *  a binding there's nothing for makes it unavailable there.
	 */
	input?: unknown | null,
	/**
	 *  What gathers its input — a page (a tab id, `oxplow:oxplow/page?page=new-task`) or one
	 *  of the window's own forms (`new-thread`, `commit`): choosing it
	 *  opens that rather than running it.
	 */
	form?: string | null,
	/**
	 *  The page to open once it ran: a tab id whose `{{result.<field>}}`
	 *  takes the result's field (`oxplow:oxplow/dashboard?id={{result.id}}`).
	 */
	open_after?: string | null,
	/**
	 *  It runs as a background task (a slow call out: pull, push) whose
	 *  failure is reported, rather than awaited where it was chosen.
	 */
	background?: boolean,
	/**
	 *  The key that runs it, as `Ctrl/Cmd+S` / `Ctrl/Cmd+Shift+N`
	 *  (`Ctrl/Cmd` is Cmd on macOS, Ctrl elsewhere).
	 */
	shortcut?: string | null,
	/**
	 *  Its shortcut runs it while the person types in a field too (Save,
	 *  Find); otherwise typing keeps it.
	 */
	while_typing?: boolean,
	/**  Where the menu bar shows it. */
	menu?: MenuPlace | null,
	/**
	 *  When it's offered — in search, the menu bar and by its shortcut —
	 *  in VS Code's when-clause syntax over the window's context keys
	 *  (`crate::when`): `fileShown && pageDirty`, `streamKind == worktree`.
	 *  Absent, always.
	 */
	when?: string | null,
};

export type CommitRefLabel = {
	kind: CommitRefLabelKind,
	name: string,
};

export type CommitRefLabelKind = "branch" | "tag";

/**  How a custom component sizes (`size:` in `custom_components:`). */
export type ComponentSize =
/**
 *  As tall as what it draws: its frame grows with it and the page
 *  scrolls.
 */
"content" |
/**  It takes the page's height and scrolls itself (a board's columns). */
"fill";

/**
 *  `when: { config: <pointer>, in: [<values>] }`: a contribution that is
 *  there only while a setting of its extension's own configuration is one
 *  of `in`. The one condition type every contribution kind that is offered
 *  by a setting shares.
 */
export type ConfigCondition = {
	/**
	 *  A JSON pointer into the extension's own configuration, naming a
	 *  scalar key of `configuration.schema` (`/tasks/workflow`).
	 */
	config: string,
	/**
	 *  The values for which it holds: of the key's type, and of its `enum`
	 *  when it has one.
	 */
	in: unknown[],
};

/**
 *  A versioned declaration of settings. This is data, not consent or a
 *  credential reference. Stored overrides and host services are separate.
 *  A field's default is the `default` keyword on its schema.
 */
export type ConfigurationFile = ConfigurationFile_Serialize | ConfigurationFile_Deserialize;

/**
 *  A versioned declaration of settings. This is data, not consent or a
 *  credential reference. Stored overrides and host services are separate.
 *  A field's default is the `default` keyword on its schema.
 */
export type ConfigurationFile_Deserialize = {
	version: number,
	schema: unknown,
	/**
	 *  The Settings categories its fields' `x-category` names (by id): what
	 *  each is called, what it is for, where it sits. A category it names
	 *  without declaring gets a title from its id; core's ids are core's.
	 */
	categories?: { [key in string]: CategoryDeclaration },
};

/**
 *  A versioned declaration of settings. This is data, not consent or a
 *  credential reference. Stored overrides and host services are separate.
 *  A field's default is the `default` keyword on its schema.
 */
export type ConfigurationFile_Serialize = {
	version: number,
	schema: unknown,
	/**
	 *  The Settings categories its fields' `x-category` names (by id): what
	 *  each is called, what it is for, where it sits. A category it names
	 *  without declaring gets a title from its id; core's ids are core's.
	 */
	categories?: { [key in string]: CategoryDeclaration },
};

/**
 *  Whether a person's run must be confirmed by them first (the second
 *  click). An agent's run doesn't ask: what an agent may call is its
 *  harness's to decide. An effect's run is kept as a proposal, a job's or
 *  oxplow's is refused. Ordered weakest first, so an operation's floor
 *  compares: a declaration may ask more than its operation's
 *  `confirm_at_least`, never less.
 */
export type Confirm = "never" | "always" |
/**  Irreversible; presented as destructive and always confirmed. */
"destructive";

export type ConnectHost = {
	/**  `server.tailnet.ts.net:7400`, `https://…`. */
	address: string,
	code: string,
};

/**  One key of a point's context. */
export type ContextKey = {
	name: string,
	ty: ContextType,
	/**  Declared `name?`: a page may leave it out. */
	optional: boolean,
};

/**  The type of one context key. */
export type ContextType = "string" |
/**  A ref (`oxplow:…`): a string. */
"uri" | "int" | "bool";

/**
 *  A contribution's identity within the catalog: who declared it, what
 *  kind it is, and its id there (for a [`ContributionKind::global_name`]
 *  kind, its global name). Its only public name is its ref
 *  ([`ContributionId::reference`], also its `Display`):
 *  `oxplow:oxplow/job?job=change_review/review`, `oxplow:oxplow/command?command=oxplow.tasks.clear_finished`. Storage,
 *  events, manifests and the desktop all carry that ref
 *  (`.context/resources.md` "Using refs").
 */
export type ContributionId = {
	/**
	 *  The namespace it is named in (its extension's `namespace:`), not
	 *  the extension that declares it ([`Descriptor::owner`] says that):
	 *  moving it to a sibling in the namespace keeps its id.
	 */
	namespace: string,
	kind: ContributionKind,
	local: string,
};

/**  Every kind of contribution a manifest can declare. */
export type ContributionKind = "dataset" | "measure" | "metric" | "dimension" | "collector" | "event_type" | "resource" | "command" | "job" | "ai_profile" | "effect" | "advisory" | "skill" | "agent_context" | "run_pattern" | "file_kind" | "link" | "test_convention" | "language" | "implementation" | "provider" | "page" | "panel" | "slot" | "decorator" | "replacement" | "custom_component";

/**  One credential a provider declares. */
export type CredentialDecl = {
	/**
	 *  Its name: the environment variable the provider reads it from, and
	 *  what its keychain account is named for.
	 */
	name: string,
	/**  Obtained by signing in rather than pasted (P9.B3). */
	oauth: OAuthDecl | null,
	/**  An inert host-owned secret identity: the value lives in the host's secret store. */
	secretRef: SecretRef | null,
};

/**
 *  A declared component (valid ones; invalid ones are in the extension's
 *  `errors`).
 */
export type CustomComponent = CustomComponent_Serialize | CustomComponent_Deserialize;

/**
 *  A declared component (valid ones; invalid ones are in the extension's
 *  `errors`).
 */
export type CustomComponent_Deserialize = {
	/**
	 *  `[a-z0-9-]+`, unique in the extension; a page's `component` node
	 *  names it.
	 */
	id: string,
	extension: string,
	title: string | null,
	/**  The bundle's folder inside the extension, holding `index.html`. */
	bundle: string,
	/**  Commands the component may invoke. */
	commands: string[],
	/**
	 *  Action points it may run (`invokePoint`): whatever command joined
	 *  the point for the context it gives. The store joining the point is
	 *  its consent, so no `commands:` permission is needed. Any extension's
	 *  point.
	 */
	actionPoints?: string[],
	/**
	 *  It runs its own read-only SQL over the datasets (`querySql`): needs
	 *  `sql.read` permission.
	 */
	sql?: SqlAccess | null,
	/**
	 *  One sentence saying what it is (`v_custom_component.description`);
	 *  `None` when its declaration says nothing.
	 */
	description?: string | null,
	/**
	 *  How it sizes on a page: as tall as what it draws (`content`, the
	 *  default) or the page's height, scrolling itself (`fill`).
	 */
	size?: ComponentSize,
};

/**
 *  A declared component (valid ones; invalid ones are in the extension's
 *  `errors`).
 */
export type CustomComponent_Serialize = {
	/**
	 *  `[a-z0-9-]+`, unique in the extension; a page's `component` node
	 *  names it.
	 */
	id: string,
	extension: string,
	title: string | null,
	/**  The bundle's folder inside the extension, holding `index.html`. */
	bundle: string,
	/**  Commands the component may invoke. */
	commands: string[],
	/**
	 *  Action points it may run (`invokePoint`): whatever command joined
	 *  the point for the context it gives. The store joining the point is
	 *  its consent, so no `commands:` permission is needed. Any extension's
	 *  point.
	 */
	actionPoints: string[],
	/**
	 *  It runs its own read-only SQL over the datasets (`querySql`): needs
	 *  `sql.read` permission.
	 */
	sql?: SqlAccess | null,
	/**
	 *  One sentence saying what it is (`v_custom_component.description`);
	 *  `None` when its declaration says nothing.
	 */
	description?: string | null,
	/**
	 *  How it sizes on a page: as tall as what it draws (`content`, the
	 *  default) or the page's height, scrolling itself (`fill`).
	 */
	size: ComponentSize,
};

/**
 *  One dataset as its owner declares it (an entry of `datasets.yaml`, or
 *  of an extension's `datasets:`).
 */
export type DatasetDecl = {
	name: string,
	version: number,
	description: string,
	/**  The contract: the view's fields (its columns), in order. */
	fields: DatasetField[],
	/**
	 *  How its fields point into other datasets:
	 *  `[{ from: <field>, to: <dataset>.<field> }]`. Declared, checked and
	 *  published (`v_dataset.relationships`); not part of the contract.
	 */
	relationships?: RelationshipDecl[],
	/**
	 *  The fields whose values name one row: declared fields,
	 *  part of the contract. A key implies its test (never null, never
	 *  repeated), and a materialized dataset's table takes it as its
	 *  primary key.
	 */
	key?: string[],
	tests?: TestDecl[],
	/**
	 *  Earlier versions kept published beside this one after a breaking
	 *  change, each as `<view>_v<version>` until its date.
	 */
	deprecated?: Deprecated[],
	/**
	 *  How it is computed: absent, on read (a view); `on_change`, stored
	 *  and recomputed when one of its inputs changes; `{ every: 1h }`,
	 *  stored and recomputed on that clock.
	 */
	materialize?: Materialize | null,
	/**  Guidance for an agent reading the dataset. Not part of the contract. */
	ai_context?: AiContext | null,
	/**
	 *  Other extensions' datasets may add rows to it (`adds_to:`): its
	 *  view is its own rows `UNION ALL` theirs, each with these fields.
	 */
	open?: boolean,
	/**
	 *  The open dataset this one adds its rows to, named as a `ref()`
	 *  names one (`<namespace>/<name>`). Its fields must have the open
	 *  dataset's names, in order; it still publishes as its own view too. Naming one that
	 *  isn't published (its extension is off) joins nothing.
	 */
	adds_to?: string | null,
};

/**
 *  One promised field: a column of the dataset's view.
 *
 *  Equality is the contract's: `ai_context` is guidance for an agent, not
 *  a promise, so two columns that differ only in it are equal and editing it
 *  never needs a version bump.
 */
export type DatasetField = {
	name: string,
	/**
	 *  The declared type SQLite reports for the view's column
	 *  (`PRAGMA table_info`); empty for a computed column.
	 */
	type?: string,
	doc: string,
	/**
	 *  Guidance for an agent reading the column. Not part of the contract:
	 *  left out of `dataset_contract` and the golden, stored on the dataset.
	 */
	ai_context?: AiContext | null,
};

/**  When one dataset last changed. */
export type DatasetFreshness = {
	dataset: string,
	/**  RFC 3339. */
	changedAt: string,
};

/**  A dataset's declaration and its SQL file. */
export type DatasetSource = {
	decl: DatasetDecl,
	/**  Where the SQL came from, for error locations (`datasets/task.sql`). */
	file: string,
	sql: string,
	/**
	 *  For a kept earlier version (named `<name>_v<version>`): what it's a
	 *  version of. Its columns are filled from the contract that version
	 *  published when it compiles.
	 */
	twin: Twin | null,
};

/**  Where in the manifest it was declared. */
export type DeclaredAt = {
	file: string,
	/**  1-based; `None` when the kind doesn't track lines. */
	line: number | null,
};

/**  Where a decoration shows. */
export type DecoratorPlacement =
/**  A chip in the header of a page whose ref the dataset lists. */
"ref-chip" |
/**  A badge after a page cell that links to a listed ref. */
"row-badge";

/**  Where a loaded extension's files came from. */
export type Deployment =
/**
 *  Read from its source folder: an authoring check, the CLI, a
 *  standalone load.
 */
{ kind: "source" } |
/**
 *  The deployment that ships inside oxplow (a bundled extension with no
 *  deployment of its own), written to the store once per hash.
 */
{ kind: "shipped"; hash: string } |
/**  A deployment in the store. */
{ kind: "deployed"; hash: string } |
/**  Its source is here but it has no deployment yet: listed, not run. */
{ kind: "undeployed" } |
/**
 *  Listed as on, but neither its source nor a deployment is on this
 *  machine: listed, not run, and not an error.
 */
{ kind: "not_here" };

/**
 *  An earlier version kept after a breaking change: its SQL (in `file`,
 *  beside the dataset's) still keeps the contract that version published,
 *  until `until` (`YYYY-MM-DD`).
 */
export type Deprecated = {
	version: number,
	file: string,
	until: string,
};

/**  Everything a contribution is, as core knows it. */
export type Descriptor = {
	id: ContributionId,
	owner: Owner,
	/**
	 *  The contract's own version (a dataset's, an event type's), when it
	 *  has one.
	 */
	contract_version: number | null,
	trigger: RunsOn,
	/**
	 *  What it requires: capabilities, features or scopes
	 *  (`capability::check_need`'s forms). Never what it was granted.
	 */
	needs: string[],
	/**
	 *  What it runs after when an event reaches it and them (an effect's
	 *  or a collector's `after:`), as refs once the catalog resolved them
	 *  (`oxplow_domain::ordering`): `effect:<ext>/<id>`,
	 *  `oxplow:oxplow/collector?collector=<ext>/<id>` or `oxplow:oxplow/consumer?name=<name>`.
	 */
	after: string[],
	/**
	 *  Where it runs among the effects and collectors one event reaches:
	 *  0 first, each after every contribution it names. `None` for a kind
	 *  that isn't ordered.
	 */
	order_level: number | null,
	/**
	 *  The name it takes in a space extensions share (a metric key, an
	 *  event type, a skill name, `<capability>/<id>`); two contributions
	 *  of a kind that doesn't share names can't hold the same one.
	 */
	global: string | null,
	/**
	 *  One sentence saying what it is, for the kinds whose declaration
	 *  carries one (a collector's `doc:`); `None` otherwise.
	 */
	description: string | null,
	source: DeclaredAt,
};

export type DeviceView = {
	id: string,
	name: string,
	/**  `desktop`, `tablet` or `phone`. */
	kind: string,
	/**  Seconds since the Unix epoch. */
	pairedAt: number,
	/**  It has a window open on this host now. */
	connected: boolean,
};

export type DevicesView = {
	/**  This Mac's own name, as other devices see it. */
	thisDevice: string,
	devices: DeviceView[],
	/**  "Allow other devices", as saved. */
	settings: HostSettings,
	/**  Whether the host runs with them now (they apply at the next start). */
	settingsApplied: boolean,
	/**  The addresses a device opens: `https://<name>:<port>/`. */
	openOnDevice: string[],
	/**  Where the host listens for other devices now, or why it cannot. */
	public: PublicListener | null,
	/**  Why the host did not answer: the settings still show, to fix. */
	hostError: string | null,
};

/**  One problem. */
export type Diagnostic = {
	severity: Severity,
	/**
	 *  Stable and dotted, by family: `manifest.name_mismatch`,
	 *  `page.unknown_column`, `fixture.compare`.
	 */
	code: string,
	/**
	 *  Relative to the extension's folder; `None` when no one file is at
	 *  fault (a cycle of `requires:`).
	 */
	file: string | null,
	/**  1-based. */
	line: number | null,
	/**
	 *  What it is about: a contribution's URI
	 *  (`oxplow:oxplow/effect?effect=acme/notify`) or a command's bus id.
	 */
	contribution: string | null,
	message: string,
	/**  What to change, when the check knows. */
	fix: string | null,
	/**
	 *  A fixture's comparison that didn't hold (boxed: only fixtures carry
	 *  one, and every other diagnostic stays small).
	 */
	mismatch: Mismatch | null,
};

/**
 *  One entry in the top-level `dimensions:` block — the **conformed-dimension
 *  catalog** authoring surface. A dimension is a
 *  slice axis that means the same thing to every fact that carries it
 *  (`oxplow.severity`, `acme.license`, …), enabling cross-metric drill-across.
 *  Like [`MeasureEntry`] it is definition-only; the `oxplow.*` built-ins are the
 *  migration seed. Resolved by [`resolve_dimensions`] and seeded into the
 *  `dimension` table at boot; `promote` requests a generated column + index
 *  (catalog teeth).
 */
export type DimensionEntry = {
	/**  The new dimension's namespaced key (`<vendor>.<id>`). Required. */
	key?: string | null,
	label?: string | null,
	/**
	 *  `categorical` | `numeric` | `temporal` | `entity-ref` (default
	 *  `categorical`).
	 */
	valueType?: string | null,
	/**  For `entity-ref` dims — the subject kind the value points at. */
	subjectKind?: string | null,
	/**  Optional controlled vocabulary (the allowed value set). */
	vocabulary?: string[],
	/**
	 *  Request a generated column + expression index on `fact` for this dim
	 *  (fast group-by/filter). Off by default — the long tail lives in
	 *  `dims_json`, promoted only when hot.
	 */
	promote?: boolean,
	/**
	 *  Entity dimension: the `v_*` view it slices, for entity
	 *  metrics over the same view.
	 */
	entity?: string | null,
	/**  Entity dimension: the SQL expression (over the view, aliased `e`). */
	expr?: string | null,
	/**
	 *  Entity dimension: an optional join, e.g.
	 *  `LEFT JOIN v_thread t ON t.id = e.thread_id`.
	 */
	join?: string | null,
	/**
	 *  A fact dimension an extension's dataset answers: the fact's `by` key
	 *  (`request_id`, `thread_id`, `turn_id` or `stream_id`) is looked up in
	 *  the dataset's column of the same name, and the dimension's value is the
	 *  dataset's `value` column of the first row in `order`. Core names no
	 *  dataset: with the extension off the dimension is absent and the fact
	 *  has no value on it.
	 */
	from?: DimensionFrom | null,
	/**  Guidance for an agent reading the dimension. */
	ai_context?: AiContext | null,
	/**  One sentence saying what the dimension slices by (`v_dimension.description`). */
	description?: string | null,
};

/**  Where a `from:` dimension reads its value (see [`DimensionEntry::from`]). */
export type DimensionFrom = {
	/**  The `v_*` view of the dataset that answers. */
	dataset: string,
	/**
	 *  The fact key the dataset is looked up by, and its column of the same
	 *  name: `request_id`, `thread_id`, `turn_id` or `stream_id`.
	 */
	by: string,
	/**  The dataset column that holds the dimension's value. */
	value: string,
	/**
	 *  A SQL ordering over the dataset's columns; the first row wins. Without
	 *  it, the dataset's own order.
	 */
	order?: string | null,
};

/**  How the shell draws a point. */
export type Draws =
/**  No contributor: nothing is drawn. */
"none" |
/**  One: a button that runs it. */
"button" |
/**  Several: a menu of them. */
"menu";

/**
 *  Where a dragged row landed: the rows on either side of the drop
 *  (`before`: the one below it, `after`: the one above), the row it was
 *  dropped on, and the value of the group it was dropped in. What isn't
 *  there is `None` (a drop at a list's end has no row below). `order` is
 *  every row of the result in its order after the drop (the dragged rows
 *  moved to where they landed; a drop onto a row leaves it as it was).
 */
export type Drop = {
	before?: { [key in string]: SqlCell } | null,
	after?: { [key in string]: SqlCell } | null,
	onto?: { [key in string]: SqlCell } | null,
	group?: SqlCell | null,
	order?: { [key in string]: SqlCell }[] | null,
};

/**
 *  An effect as loaded (valid ones; invalid ones are in the extension's
 *  `errors`).
 */
export type EffectDecl = {
	id: string,
	/**  The extension that declares it: whose script and grants it runs. */
	extension: string,
	/**  The namespace it is named in: its name's first part. */
	namespace: string,
	summary: string,
	/**  The event types it reacts to. */
	on: string[],
	/**
	 *  Payload fields that must equal these values (the collectors'
	 *  `where`).
	 */
	filter: { [key in string]: string[] },
	/**
	 *  The scopes its script calls (`scope(id, args)`,
	 *  `.context/commands.md` "Scopes"): `sql.read`.
	 */
	needs: string[],
	/**  The script's path in the folder. */
	entry: string,
	/**  Its source. */
	script: string,
	/**
	 *  What it runs after on one event, as written (resolved to refs on
	 *  its descriptor; `extensions-events.md` "Ordering").
	 */
	after: string[],
	/**  `file:line` of the declaration. */
	declaredAt: string,
};

export type EntityColumn = {
	name: string,
	colType: ColumnType,
	doc: string,
};

/**  An entity a collector writes: its rows, published as a view. */
export type EntityDecl = {
	name: string,
	doc: string,
	/**  Column that uniquely identifies a row. */
	key: string,
	columns: EntityColumn[],
	relations: EntityRelation[],
	/**  SQL name pages and agents query: `v_<namespace>_<entity>`. */
	view: string,
};

/**
 *  A documented join from an entity to another view. Not executed; it
 *  tells agents and page authors how the data connects.
 */
export type EntityRelation = {
	/**  The view it joins to, e.g. `v_oxplow_task` or `v_github_review`. */
	to: string,
	/**  The SQL join condition, e.g. `v_github_pr.head_branch = v_stream.branch`. */
	on: string,
};

/**
 *  A body as read: UTF-8 (lossy) text, its full size, and whether what is
 *  returned is less than the whole (capped at store or at read).
 */
export type EventBody = {
	text: string,
	size: number,
	truncated: boolean,
};

/**  Which body of the event. */
export type EventBodyKey = "input" | "output" |
/**  An `agent.prompt.submitted`'s text. */
"prompt" |
/**  An `agent.subagent.finished`'s last message. */
"result" |
/**  An `agent.context.compacted`'s summary. */
"summary";

/**
 *  An event's public identity: a UUIDv7 in its canonical text form, so
 *  ids sort by creation time. `seq` (the log's insert order) is the
 *  delivery order; `id` is what other events and the command run record point at.
 */
export type EventId = string;

/**  How long its events' payloads and large content are kept, in days. */
export type EventRetention = {
	payloadDays: number,
	contentDays: number,
};

/**
 *  One `type@v` an extension declares, as loaded: the schema and the
 *  upcast's script read from its folder.
 */
export type EventTypeDecl = {
	eventType: string,
	v: number,
	/**  The payload's JSON Schema (from the declared file). */
	schema: unknown,
	summary: string,
	/**  The upcast script's path in the folder, required past v1. */
	upcast: string | null,
	/**  Its source. */
	upcastSource: string | null,
	/**
	 *  `file:line` of the declaration, for what's wrong with it later (a
	 *  schema changed at a recorded version).
	 */
	declaredAt: string,
};

/**
 *  An extension's `event_types:` as loaded: its valid types, and the
 *  retention window it declares for its namespace.
 */
export type EventTypes = {
	types: EventTypeDecl[],
	/**
	 *  Shorter than the extension default (`event_retention::check_declared`);
	 *  `None`: the default.
	 */
	retention: EventRetention | null,
};

export type ExportDeclaration = {
	contribution: ContributionId,
	version: number,
	visibility: Visibility,
	source: DeclaredAt,
};

/**  A loaded extension and anything wrong with it. */
export type Extension = Extension_Serialize | Extension_Deserialize;

/**
 *  A command an extension declares (valid ones; invalid ones are in the
 *  extension's `errors`).
 */
export type ExtensionCommand = {
	/**  Its name on the bus: `<namespace>.<name>`. */
	name: string,
	summary: string,
	/**
	 *  Its input's schema; `None` for one backed by a scope's
	 *  operation (the operation's).
	 */
	inputSchema: unknown | null,
	/**  What runs it. */
	handler: CommandHandler,
	confirm: Confirm,
	/**  What a person is told when it asks (`CommandSpec::confirm_says`). */
	confirmSays: string | null,
	access: Access,
	/**
	 *  A durable job's model may call it (`job: true`, a handler of the
	 *  extension's own). Anyone else may run every command.
	 */
	job: boolean,
	/**
	 *  The scopes its script calls, and the capabilities (or features)
	 *  it needs active, as core's commands declare them
	 *  (`oxplow_domain::capability::check_need`).
	 */
	needs: string[],
	/**
	 *  How a person meets it (label, group, …), as core's commands do
	 *  (boxed, as theirs is).
	 */
	ui: CommandUi | null,
	/**
	 *  Stable: the commands of an extension that ships with oxplow are;
	 *  any other's are experimental.
	 */
	stable: boolean,
	examples: CommandExample[],
	/**
	 *  Its example input (`example:`, else a script's first example that
	 *  runs): JSON Schema's `examples` on the input schema it registers
	 *  with — what `list_commands` shows an agent and a refusal quotes.
	 */
	example: unknown | null,
	/**
	 *  The MCP tool it is also offered as (`tool:`), prefixed with its
	 *  namespace: `oxplow_query_sql` ([`tool_name`]).
	 */
	tool: string | null,
	/**  The inputs kept out of its record (`CommandSpec::unrecorded`). */
	unrecorded: string[],
};

/**
 *  A left-nav panel an extension contributes (P6.G1, target §11.3): its
 *  `body` viz renders compact in the nav; its `badge` viz's alert gives
 *  the count shown on the panel and in the Alerts panel.
 */
export type ExtensionPanel = {
	/**  `<extension>/<panel>`. */
	id: string,
	extension: string,
	title: string,
	icon: string | null,
	dataScope: PanelDataScope,
	/**  The body viz (`<extension>/<slug>`). */
	body: string,
	/**  The badge viz, which declares an `alert`. */
	badge: string | null,
	/**
	 *  The page its header opens (`oxplow:oxplow/page?page=<kind>`, a canonical ref): a core
	 *  page the panel summarizes, as Waiting on you opens its page.
	 *  Absent, the body viz's own page.
	 */
	open: string | null,
	/**
	 *  The viz shown, compact, while the panel is collapsed: its one-line
	 *  summary. Absent, a collapsed panel shows only its header.
	 */
	collapsed: string | null,
	/**
	 *  The viz whose row count (a `number` viz: its value) is the
	 *  header's count, without raising an alert. It wins over
	 *  the badge's count; the badge still feeds Alerts.
	 */
	count: string | null,
	/**
	 *  The panel lives in the bottom dock (an icon with a badge that opens
	 *  the body above the bar), not in the rail.
	 */
	dock?: boolean,
};

/**
 *  A resource an extension declares (valid ones; invalid ones are in its
 *  `errors`).
 */
export type ExtensionResource = {
	decl: ResourceDecl,
	/**  `file:line` of the declaration. */
	declaredAt: string,
};

/**  What an extension adds to the core UI (`ui:` in its manifest). */
export type ExtensionUi = {
	/**  Pages mounted at other pages' slots (valid ones). */
	pageSlots?: PageSlot[],
	/**  Labels from its datasets on core refs (valid ones). */
	decorators: UiDecorator[],
	/**
	 *  Viz nodes that take the place of a core sub-component while its
	 *  provider is the capability's active one (valid ones).
	 */
	replacements: UiReplacement[],
};

/**  A loaded extension and anything wrong with it. */
export type Extension_Deserialize = {
	name: string,
	/**
	 *  The namespace its commands' ids are under: the manifest's
	 *  `namespace:`, else the name with `-` → `_`.
	 */
	namespace: string,
	description: string,
	/**
	 *  The folder it was read from: repo-relative for a source, the
	 *  deployment's folder for a deployed copy, `bundled:<name>` for a
	 *  shipped one.
	 */
	path: string,
	/**
	 *  The repo-relative source folder a person edits, when there is one
	 *  (a deployed copy's source); `None` when `path` is that folder or
	 *  there is no source here (a shipped copy).
	 */
	source?: string | null,
	/**
	 *  Problems found while loading; empty when healthy. A page that
	 *  failed to load is listed here and missing from `page_files`. Each
	 *  names its file relative to the extension's folder: show it with
	 *  [`Extension::shown`].
	 */
	errors: Diagnostic[],
	/**
	 *  Things worth fixing that don't stop it loading: an intent with no
	 *  examples.
	 */
	warnings: Diagnostic[],
	/**  The manifest version it was read as (`manifest:`). */
	manifestVersion: number,
	/**  Why it exists (required; `None` only when the manifest didn't load). */
	intent: Intent | null,
	/**
	 *  Its page files — pages, parts and queries (`pages/`, `parts/`,
	 *  `queries/`; valid ones — invalid ones are in `errors`).
	 */
	pageFiles?: Page_Deserialize[],
	/**  Declared collectors (valid ones; invalid ones are in `errors`). */
	collectors: CollectorSpec_Deserialize[],
	/**  Declared providers (valid ones — invalid ones are in `errors`). */
	providers: ProviderSpec[],
	/**  Web components its `custom` viz nodes render, sandboxed (valid ones). */
	customComponents: CustomComponent_Deserialize[],
	/**
	 *  Event types it declares (valid ones — the vocabulary registers
	 *  them, `vocabulary_reactor`).
	 */
	eventTypes: EventTypes,
	/**
	 *  Resources it declares (valid ones — the vocabulary registers
	 *  them, `vocabulary_reactor`).
	 */
	resources: ExtensionResource[],
	/**
	 *  Effects it declares (valid ones; each reacts once the extension is
	 *  deployed, `effects`).
	 */
	effects: EffectDecl[],
	/**
	 *  The capability implementations it declares (`implementations:`,
	 *  each a built-in of core's).
	 */
	implementations: ImplementationDecl[],
	/**
	 *  Skills and slash commands it gives the coding agent (`skills:`;
	 *  valid ones — invalid ones are in `errors`).
	 */
	skills: SkillDecl[],
	/**
	 *  What it puts in the coding agent's context (`context:`; valid
	 *  ones — invalid ones are in `errors`).
	 */
	contexts: AgentContextDecl[],
	/**
	 *  The command substrings it says mark a test or analysis run
	 *  (`run_patterns:`; valid ones — invalid ones are in `errors`).
	 */
	runPatterns: RunPatternDecl[],
	/**
	 *  The kinds of file it names by glob (`file_kinds:`; valid ones —
	 *  invalid ones are in `errors`).
	 */
	fileKinds: FileKindDecl[],
	/**
	 *  The text it makes links of (`links:`; valid ones — invalid ones are
	 *  in `errors`): the terminal and markdown match them.
	 */
	links: LinkRuleDecl[],
	/**
	 *  What makes a file, container or function a test, and what counts as
	 *  an assertion or a skip (`test_conventions:`; valid ones — invalid
	 *  ones are in `errors`).
	 */
	testConventions: TestConventionDecl[],
	/**
	 *  Another extension's event types its effects and collectors react
	 *  to (P9.D1): each resolves when an enabled extension registers the
	 *  type (`vocabulary_reactor`).
	 */
	subscriptions: ForeignSubscription[],
	/**
	 *  `project` (in `.oxplow/extensions/`) or `bundled` (ships with oxplow,
	 *  read-only).
	 */
	origin: string,
	/**  What it adds to the core UI (`ui:`). */
	ui: ExtensionUi,
	/**
	 *  False when configuration disables it or public contracts block it;
	 *  an inactive extension contributes nothing to the runtime catalog.
	 */
	enabled: boolean,
	/**  Guidance for the coding agent (valid ones; invalid ones are in `errors`). */
	advisories: Advisory[],
	/**
	 *  Measures and metrics it contributes to the metric catalog (the
	 *  `project.yaml` schema). Metrics are `key:` definitions and are on
	 *  while the extension is enabled; the facts they read come from its
	 *  collectors (`collectors:` with `facts:`).
	 */
	measures: MeasureEntry[],
	metrics: MetricEntry[],
	/**
	 *  Dimensions it contributes (fact or entity), never promoted: an
	 *  extension toggling would rebuild the metric cube each time.
	 */
	dimensions: DimensionEntry[],
	/**
	 *  Its datasets (`datasets:` plus `datasets/<name>.sql`), published as
	 *  `v_<namespace>_<name>` (`extension_datasets`). Empty when any
	 *  declaration is broken (see `errors`).
	 */
	datasets: DatasetSource[],
	/**
	 *  Left-nav panels it contributes (valid ones; invalid ones are in
	 *  `errors`).
	 */
	panels: ExtensionPanel[],
	/**
	 *  Commands it registers on the bus, each a Starlark script composing
	 *  core commands (P6b; valid ones — invalid ones are in `errors`).
	 */
	commands: ExtensionCommand[],
	/**  Durable host operations declared by this extension. */
	jobs: JobDecl[],
	/**  Named dataset needs this extension declares. */
	aiProfiles: AiProfileDecl[],
	/**  Action points it declares (`action_points:`; valid ones). */
	actionPoints: ActionPointDecl[],
	/**  Its `version:` (semver), when it declares one; required to share. */
	version: string | null,
	/**
	 *  Its contributions as descriptors (`extensions::descriptors`): the
	 *  kinds that have moved onto them so far.
	 */
	contributions: Descriptor[],
	/**  Validated non-secret settings declaration, not resolved values or grants. */
	configuration?: ConfigurationFile_Deserialize | null,
	publicContracts?: PublicContracts,
	/**  Where its files came from. */
	deployment?: Deployment,
	/**
	 *  What its manifest declares it may reach beyond the baseline
	 *  (`permissions:`).
	 */
	permissions?: Permissions,
	/**  The other extensions it needs on (`requires:`). */
	requires?: string[],
	/**  What a deploy builds before it copies (`build:`). */
	build?: Build_Deserialize | null,
	/**
	 *  What it waits on a person for when it is on but undeployed: the
	 *  permissions its source would add, one line each
	 *  ([`Permissions::added_over`]), and its build command when it has one
	 *  (`extension_deploy::build_line`): what its deploy will ask.
	 */
	pending?: string[],
	/**
	 *  It is the team's: the project's own list names it
	 *  (`oxplow.extension.share`).
	 */
	shared?: boolean,
};

